+fn tracked_pods_summary(tracked: &HashMap<String, PodInfo>, port: u16) -> String {
+    let mut pods = tracked
+        .values()
+        .map(|pod| {
+            format!(
+                "name={} ip={} status={} is_ready={} worker_url={}",
+                pod.name,
+                pod.ip,
+                pod.status,
+                pod.is_ready,
+                pod.worker_url(port)
+            )
+        })
+        .collect::<Vec<_>>();
+    pods.sort();
+    format!("count={} pods=[{}]", tracked.len(), pods.join("; "))
+}
